const TOP_SIZE = 3
save scores_cmdtest
when player_chat {
    if not var.exists(scores_cmdtest) { scores_cmdtest = {} }
    args = split_text(value.event_chat_message, " ")
    if args[0] != "@score" { end_thread() }
    cancel_event()
    if len(args) < 3 { send_message("&cНужно: @score <ник> <очки>"); end_thread() }
    old = get_map_value_single(scores_cmdtest, args[1], 0)
    scores_cmdtest[args[1]] = old + add(args[2])
    sorted = sort_any_map(scores_cmdtest, sort_order: descending, sort_type: values)
    place = 0
    for nick: points in sorted {
        place += 1
        if place > TOP_SIZE { break }
        send_message("&e${place}. &f${nick} &7— ${points}")
    }
}

