func to_ms(s: text) {
    units = {"s": 1000, "m": 60000, "h": 3600000, "d": 86400000}
    total = 0
    buf = ""
    for ch in split_text(s, "%empty%") {
        if ch in units {
            n = add(buf)
            total += n * get_map_value_single(units, ch, 0)
            buf = ""
        } else {
            buf = "${buf}${ch}"
        }
    }
    return total
}

